@js:
var html=result;
headers={"headers":{"Referer":baseUrl}};
cid=result.match(/qTcms_S_m_id="(.*?)"/)[1];
u='http://www.manhuatt.com/statics/pic/?p=';
key='&picid='+cid+'&pinyin=zuozuokezhan&m_httpurl=&fenye=0';

(function getImgList() {
    eval(html.match(/(var qTcms_Cur=[\S\s]+var qTcms_S_show_1=.*?;)/)[1]);
    var list = java.base64Decode(qTcms_S_m_murl_e).split("\\$qingtiandy\\$");
    var piclist = new Array();
    for (var i = 0; i < list.length; i++) {
        var v = list[i];
        var s = v;
        if (v.substring(0, 1) == "/") {
            s = qTcms_m_weburl + s;
        } else {
            if (qTcms_Pic_m_if != "2") {
                v = v.replaceAll("\\?", "a1a1");
                v = v.replaceAll("&", "b1b1");
                v = v.replaceAll("%", "c1c1");
                var m_httpurl = "";
                if (typeof(qTcms_S_m_mhttpurl) != "undefined") m_httpurl = java.base64Decode(qTcms_S_m_mhttpurl);
            }
        }
        piclist[i] =s;
    }
    return piclist;
}()).map(uri=>
'<img src="'+u+uri+key+','+JSON.stringify(headers)+'">').join("\n")

